window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"EQXHpLqnagc","speaker":"Maria Malmer Stenergard","role":"Foreign Minister","country":"Sweden","region":"Europe","url":"https://www.youtube.com/watch?v=EQXHpLqnagc","date":"20260926","title":"🇸🇪 Sweden - Foreign Minister Addresses United Nations General Assembly 81st Session | #UNGA","seconds":722,"words":1408,"counts":{"claims":22,"promises":3,"attacks":4},"topics":[{"topic":"Russia","share":0.364,"seconds":263},{"topic":"UN reform","share":0.3634,"seconds":262},{"topic":"Women's rights","share":0.1745,"seconds":126},{"topic":"Climate","share":0.0981,"seconds":71}],"timeline":[[2,85,null],[86,150,"Women's rights"],[150,213,"Women's rights"],[215,276,"Russia"],[277,344,"Russia"],[345,416,"Russia"],[418,481,"Russia"],[482,553,"Climate"],[555,619,"UN reform"],[619,680,"UN reform"],[680,742,"UN reform"],[743,819,"UN reform"]],"stances":{"Women's rights":"Maria Malmer Stenergard states that women's economic empowerment is a matter of freedom and notes that while Sweden made progress in the 1940s and 50s, many women remain economically dependent on men today.","Russia":"Maria Malmer Stenergard states that Russia's aggression against Ukraine is a blatant violation of international law and notes that the principles of sovereignty and territorial integrity are being challenged globally.","Climate":"Sweden will continue to promote climate action based on scientific urgency and economic opportunity.","UN reform":"Sweden strongly supports the UN80 initiative and expects full engagement from UN entities and member states to improve delivery and align mandates with resources."},"claims":[{"t":86,"quote":"One woman came to the bank holding two safe deposit keys without knowing which bank they belonged to.","topic":"Women's rights","kind":"fact"},{"t":111,"quote":"But two generations later, far too many women are still entirely economically dependent on men.","topic":"Women's rights","kind":"fact"},{"t":122,"quote":"80 years ago when Sweden joined the United Nations, the foundations of our modern society were being laid.","topic":"Women's rights","kind":"fact"},{"t":130,"quote":"In the 1940s and 50s, Swedish women joined the labor market in large numbers.","topic":"Women's rights","kind":"fact"},{"t":170,"quote":"In 1919, the same year my grandmother was born, Sweden decided that women should have the right to vote.","topic":"Women's rights","kind":"fact"},{"t":180,"quote":"That very same year, women in Afghanistan were also granted the right to vote.","topic":"Women's rights","kind":"fact"},{"t":216,"quote":"when Sweden joined the UN in 1946, the world was emerging from the devastation of war.","topic":"Russia","kind":"fact"},{"t":259,"quote":"In Ukraine, Sudan, Yemen, Palestine, Lebanon, Myanmar, the Democratic Republic of the Congo, and many other conflict zones. Millions are suffering.","topic":"Russia","kind":"fact"},{"t":302,"quote":"Russia has not only violated the UN charter, it has repeatedly violated international humanitarian law and human rights law.","topic":"Russia","kind":"fact"},{"t":309,"quote":"Attacks targeting civilians, forcible transfer of and deportation of children, conflict related sexual violence and torture, the list is far too long.","topic":"Russia","kind":"fact"},{"t":368,"quote":"4 and a half years after launching its fullscale invasion, Russia has failed to achieve its objectives.","topic":"Russia","kind":"fact"},{"t":374,"quote":"Its economy is under strain and its casualty numbers are devastating.","topic":"Russia","kind":"fact"},{"t":380,"quote":"Ordinary Russians are withdrawing their funds from the bank and a substantial share of Russia's young people are dying on the front lines.","topic":"Russia","kind":"fact"},{"t":442,"quote":"Sweden has been an active contributor to the United Nations for 80 years","topic":"Russia","kind":"fact"},{"t":463,"quote":"Sweden's first peacekeepers, 300 of them, served this organization during the Swiss crisis in 1956","topic":"Russia","kind":"number"},{"t":472,"quote":"Since then, more than 800,000 Swedes have followed in their footsteps","topic":"Russia","kind":"number"},{"t":482,"quote":"It began in 1948 with UN's first mediator, Sweden's We have long been a major donor of development assistance","topic":"Climate","kind":"fact"},{"t":512,"quote":"reducing emissions to curb climate change is a common and global challenge and is necessary to safeguard and increase development gains","topic":"Climate","kind":"fact"},{"t":580,"quote":"Assessed contributions must be paid in full and in time.","topic":"UN reform","kind":"fact"},{"t":656,"quote":"Africa, home to 1.3 billion people and the largest regional block in the United Nations, has no permanent seat.","topic":"UN reform","kind":"fact"},{"t":734,"quote":"Mr. President this year also marks 65 years since Secretary General Dog Hammerald died.","topic":"UN reform","kind":"fact"},{"t":753,"quote":"Sweden continues to support the UN investigation aimed at clarifying the circumstances surrounding Secretary General Hamahul's death.","topic":"UN reform","kind":"fact"}],"promises":[{"t":296,"quote":"We will support Ukraine for as long as it takes.","topic":"Russia","kind":"promise"},{"t":451,"quote":"we will continue to push for a UN that is more effective, more transparent, and better equipped to uphold the principles of its charter","topic":"Russia","kind":"promise"},{"t":524,"quote":"Sweden will continue to promote climate action based on urgency and opportunity.","topic":"Climate","kind":"promise"}],"attacks":[{"t":272,"quote":"Russia's aggression against Ukraine is a blatant violation of international law.","topic":"Russia","target":"Russia"},{"t":302,"quote":"Russia has not only violated the UN charter, it has repeatedly violated international humanitarian law and human rights law.","topic":"Russia","target":"Russia"},{"t":345,"quote":"Russia must also be held accountable for its breaches of the Chemical Weapons Convention, both on and off the battlefield.","topic":"Russia","target":"Russia"},{"t":355,"quote":"Russia's war of aggression against a peaceful neighbor is one of the biggest strategic mistakes and moral failures of the 21st century.","topic":"Russia","target":"Russia"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":null,"text":"I now give the floor to her excellency Maria Malma Stenagard, Minister of Foreign Affairs of Sweden. Mr. President Excellencies, I want to tell you about my grandmother Alice. Growing up in rural Sweden, as the seventh of 11 siblings, her opportunities were very different from those of her brothers. Her parents expected her to focus first and foremost on family life. Yet, she was curious, capable, and determined to build a life of her own. A job at a local bank gave her not only an income, but also independence and confidence. There at the bank, she met many women with little to no experience with finances and who were left vulnerable when circumstances She wrote in her diary about some of the women she met, many of whom were recently widowed, coming to the bank in tears because they didn't know anything about their own family finances."},{"t":86,"topic":"Women's rights","text":"One woman came to the bank holding two safe deposit keys without knowing which bank they belonged to. My grandmother was as independent as a woman in that time and place could be. But she worried deeply about the consequences for the women who were not. During her life, she witnessed extraordinary progress. But two generations later, far too many women are still entirely economically dependent on men. Mr. president. 80 years ago when Sweden joined the United Nations, the foundations of our modern society were being laid. In the 1940s and 50s, Swedish women joined the labor market in large numbers. This was not only a matter of principle. It also came from the realization that our econ economy needed women in the workforce. Women's economic empowerment is a matter of freedom."},{"t":150,"topic":"Women's rights","text":"When women work and earn their own money, their self-determination grows. Gender equality is not only the right thing to do, it's also the smart thing to do. When women work, economies grow. Mr. President, each generation must fight for equality. In 1919, the same year my grandmother was born, Sweden decided that women should have the right to vote. That very same year, women in Afghanistan were also granted the right to vote. More than a century later, the contrast between women's freedoms in our two countries is as striking as it is saddening. It is a painful reminder that progress is never irreversible. Rights once gained can be lost. Freedoms do not defend themselves. It is up to us to protect them. for women and girls everywhere and for generations to come."},{"t":215,"topic":"Russia","text":"Mr. President, when Sweden joined the UN in 1946, the world was emerging from the devastation of war. The lesson from that catastrophe was clear. Peace must not be taken for granted. Defense of sovereignty and territorial integrity has been at the heart of Swedish foreign policy ever since. Eight decades later, these principles are once again being challenged. Bad faith, conflict, and utter contempt for the common rules are weakening the institutions that we build together. These are times of upheaval. The number of armed conflicts is growing and civilians are paying the price. In Ukraine, Sudan, Yemen, Palestine, Lebanon, Myanmar, the Democratic Republic of the Congo, and many other conflict zones. Millions are suffering. Mr. President, Russia's aggression against Ukraine is a blatant violation of international law."},{"t":277,"topic":"Russia","text":"It strikes at the heart of the very principles upon which the United Nations was founded. Sweden's support for Ukraine is felt deeply throughout our entire society. It comes from our people, our civil society, and the business community. We will support Ukraine for as long as it takes. Russia has not only violated the UN charter, it has repeatedly violated international humanitarian law and human rights law. Attacks targeting civilians, forcible transfer of and deportation of children, conflict related sexual violence and torture, the list is far too long. Ensuring accountability for these violations is crucial. If there is anything that we have learned from history, it is that there cannot be a just and lasting peace without Sweden stands firmly behind the ICC, its independence and integrity, and recognizes its vital role, not least in Ukraine."},{"t":345,"topic":"Russia","text":"Russia must also be held accountable for its breaches of the Chemical Weapons Convention, both on and off the battlefield. Russia's war of aggression against a peaceful neighbor is one of the biggest strategic mistakes and moral failures of the 21st century. 4 and a half years after launching its fullscale invasion, Russia has failed to achieve its objectives. Its economy is under strain and its casualty numbers are devastating. Ordinary Russians are withdrawing their funds from the bank and a substantial share of Russia's young people are dying on the front lines. The impact of Russia's war of aggression extends far beyond Ukraine. Russia intensified its systematic attacks on civilian infrastructure and on vessels in the Black Sea this summer. This has once again disrupt disrupted global food supply chains, exacerbating an already dire situation for vulnerable people across the globe."},{"t":418,"topic":"Russia","text":"To President Putin and Mr. Lavrov, I say this. The path to peace is clear. The choice should be easy. Withdraw your troops. end this war. Mr. President, Sweden has been an active contributor to the United Nations for 80 years, and we remain committed. But as a staunch partner, we will continue to push for a UN that is more effective, more transparent, and better equipped to uphold the principles of its charter. A UN that is resolute. Sweden's first peacekeepers, 300 of them, served this organization during the Swiss crisis in 1956. Since then, more than 800,000 Swedes have followed in their footsteps. We have a long tradition of supporting mediation through the UN."},{"t":482,"topic":"Climate","text":"It began in 1948 with UN's first mediator, Sweden's We have long been a major donor of development assistance and we remain devoted to tackling global development challenges and contributing to urgent humanitarian efforts. Sweden remains a generous donor, but development assistance alone will not be enough to meet the challenges before us. Mr. President, reducing emissions to curb climate change is a common and global challenge and is necessary to safeguard and increase development gains in the coming decades. Sweden will continue to promote climate action based on urgency and opportunity. Urgency based on what science tells us. Opportunity based on the economic growth, jobs, and strengthened competitiveness that climate transition Given the state of the world, changes are necessary to ensure the UN's central role in international affairs and its ability to address today's challenges."},{"t":555,"topic":"UN reform","text":"An efficient, effective, nimble, and well-coordinated UN is urgently needed. Sweden strongly supports the Secretary General's UN80 initiative and expects all UN entities to engage fully with a clear focus on improving delivery at country level. We also expect member states to give the UN adequate resources. Assessed contributions must be paid in full and in time. As members, we also need to carefully consider institutional reforms and align mandates with available resources. UN80 is an opportunity to strengthen the UN's impact across all three pillars and to reinforce the international system firmly grounded in the UN Charter of International Law. Sweden remains firm in its defense of the UN's normative mandates on human rights, gender equality, and sexual and reproductive health and rights."},{"t":619,"topic":"UN reform","text":"Everyone has the right to live freely and with dignity, to be who they are, and to love whom they choose. Sweden will always stand up for that freedom and for equal rights of all. Mr. President, a balanced expansion of the Security Council would strengthen its credibility and the legitimacy of its decisions. Sweden would like to see permanent and non-permanent seats added and a fairer representation of all continents on the Africa, home to 1.3 billion people and the largest regional block in the United Nations, has no permanent seat. This is neither logical nor fair. Further, the veto should never be used to prevent the UN from acting against serious violations of international law or in humanitarian disasters. Mr."},{"t":680,"topic":"UN reform","text":"President, we must continue to strengthen our United Nations to make the organization stronger and better equipped to prevent conflict and meet the challenges of tomorrow. We must continue to find common agreements based on the fundamentals, every country's sovereignty and territorial integrity, prohibition of the use of force, respect for international law, human rights and humanitarian principles. It is our shared responsibility to ensure that the UN remains relevant, effective, and resolute, that it becomes greater than the sum of its parts to show once again that we can turn the page on conflict and chaos and move towards peace and prosperity. Mr. President this year also marks 65 years since Secretary General Dog Hammerald died."},{"t":743,"topic":"UN reform","text":"His integrity, conviction, and commitment to the vision and values of our organization are still Sweden continues to support the UN investigation aimed at clarifying the circumstances surrounding Secretary General Hamahul's death. And I would like to conclude with the words of Mr. Hammer. It is no news to anybody, but we sense it in different degrees that the world of today is more than ever before one world. The weakness of one is the weakness of all. And the strength of one, not the military strength, the real strength, the economic and social strength, the happiness of the people is indirectly the strength of all. Thank I thank the Minister of Foreign Affairs of Sweden."}],"compare":[{"topic":"Russia-Ukraine War","share":0.364,"mean":0.0336,"rank":5,"others":44},{"topic":"UN & its reform","share":0.3634,"mean":0.2039,"rank":27,"others":170},{"topic":"Human Rights","share":0.1745,"mean":0.0077,"rank":2,"others":24},{"topic":"Climate Change","share":0.0981,"mean":0.0425,"rank":29,"others":77}]};
